sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
	var departureDate = g_form.getValue('departure_date');
	if(!departureDate) return;
	var returnDate = new Date(newValue);
	var departure = new Date(departureDate);

	returnDate.setHours(0, 0, 0, 0);
	departure.setHours(0, 0, 0, 0);
	if(returnDate<departure){
		g_form.showFieldMsg('return_date','Return Date cannot be earlier than Departure Date.','error');
	}
   //Type appropriate comment here, and begin script below
   //  Return date validation

}
